  event?: Prisma.EventOmit
  workflow?: Prisma.WorkflowOmit
  workflowStep?: Prisma.WorkflowStepOmit
  experience?: Prisma.ExperienceOmit
  customer?: Prisma.CustomerOmit
  visit?: Prisma.VisitOmit
